/**
 * Per-bot performance report CLI (v34).
 *
 *     npm run report --workspace @fleet/api -- --bot snapback --days 30
 *
 * Reads a persisted event-history file (the API's /data/event-history.json
 * in Docker) and prints a per-bot report generated by the shared
 * @fleet/shared generator — the same code behind GET /reports. JSON
 * output is the canonical AI input; Markdown is the human twin.
 *
 * History file shapes accepted:
 *   - v2 persisted store: {version:2, protected:[], sim:[], recent:[]}
 *   - history snapshot:   {events:[...]}
 *   - a bare array of FleetEvent
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import {
  generateBotReport,
  generateFleetReports,
  renderBotReportMarkdown,
  renderFleetReportMarkdown,
  type FleetEvent,
} from "@fleet/shared";

interface CliArgs {
  bot: string;
  days: number | null;
  from: string | null;
  to: string | null;
  format: "json" | "md";
  history: string;
  startingEquity: number | null;
  out: string | null;
}

function parseArgs(argv: string[]): CliArgs {
  const args: CliArgs = {
    bot: "all",
    days: null,
    from: null,
    to: null,
    format: "md",
    history:
      process.env.EVENT_HISTORY_PATH ?? "./data/event-history.json",
    startingEquity: null,
    out: null,
  };
  for (let i = 0; i < argv.length; i += 1) {
    const flag = argv[i]!;
    const value = argv[i + 1];
    const need = (): string => {
      if (value === undefined) throw new Error(`missing value for ${flag}`);
      i += 1;
      return value;
    };
    switch (flag) {
      case "--bot":
        args.bot = need();
        break;
      case "--days": {
        const n = Number(need());
        if (!Number.isFinite(n) || n <= 0) throw new Error("--days must be a positive number");
        args.days = n;
        break;
      }
      case "--from":
        args.from = need();
        if (Number.isNaN(Date.parse(args.from))) throw new Error(`invalid --from date: ${args.from}`);
        break;
      case "--to":
        args.to = need();
        if (Number.isNaN(Date.parse(args.to))) throw new Error(`invalid --to date: ${args.to}`);
        break;
      case "--format": {
        const f = need();
        if (f !== "json" && f !== "md") throw new Error("--format must be json or md");
        args.format = f;
        break;
      }
      case "--history":
        args.history = need();
        break;
      case "--startingEquity": {
        const n = Number(need());
        if (!Number.isFinite(n) || n <= 0) throw new Error("--startingEquity must be a positive number");
        args.startingEquity = n;
        break;
      }
      case "--out":
        args.out = need();
        break;
      default:
        throw new Error(`unknown argument: ${flag}`);
    }
  }
  return args;
}

export function loadHistoryEvents(path: string): FleetEvent[] {
  if (!existsSync(path)) {
    throw new Error(`history file not found: ${path}`);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(path, "utf8"));
  } catch (err) {
    throw new Error(
      `could not parse history file ${path}: ${err instanceof Error ? err.message : String(err)}`,
    );
  }
  if (Array.isArray(parsed)) return parsed as FleetEvent[];
  if (typeof parsed === "object" && parsed !== null) {
    const obj = parsed as Record<string, unknown>;
    if (Array.isArray(obj.events)) return obj.events as FleetEvent[];
    const buckets = ["protected", "sim", "recent"]
      .flatMap((k) => (Array.isArray(obj[k]) ? (obj[k] as FleetEvent[]) : []));
    if (buckets.length > 0 || "version" in obj) return buckets;
  }
  throw new Error(`unrecognized history file shape: ${path}`);
}

function main(): void {
  let args: CliArgs;
  try {
    args = parseArgs(process.argv.slice(2));
  } catch (err) {
    console.error(`[report] ${err instanceof Error ? err.message : String(err)}`);
    process.exit(1);
  }

  let events: FleetEvent[];
  try {
    events = loadHistoryEvents(args.history);
  } catch (err) {
    console.error(`[report] ${err instanceof Error ? err.message : String(err)}`);
    process.exit(1);
  }

  let from = args.from;
  if (from === null && args.days !== null) {
    from = new Date(Date.now() - args.days * 86_400_000).toISOString();
  }
  const opts = { from, to: args.to, startingEquityUsd: args.startingEquity };

  let output: string;
  if (args.bot === "all") {
    const botList = [...new Set(events.map((e) => e.bot))].filter(
      (b) => b !== "system",
    );
    const reports = generateFleetReports(events, opts, botList);
    output =
      args.format === "json"
        ? JSON.stringify(
            {
              generatedAt: reports[0]?.generatedAt ?? new Date().toISOString(),
              timeframe: { from, to: args.to },
              reports,
            },
            null,
            2,
          )
        : renderFleetReportMarkdown(reports);
  } else {
    const report = generateBotReport(events, { ...opts, bot: args.bot });
    output =
      args.format === "json"
        ? JSON.stringify(report, null, 2)
        : renderBotReportMarkdown(report);
  }

  if (args.out) {
    writeFileSync(args.out, output.endsWith("\n") ? output : output + "\n");
    console.error(`[report] wrote ${args.out}`);
  } else {
    console.log(output);
  }
}

main();
